import { buildErrorText, buildHelpText } from './cli_text.mjs';
import { canConsumeOptionValue } from './token_rules.mjs';

const EXPECTED_VALUE_MESSAGE = 'argument --a: expected one argument';
const REQUIRED_ARGUMENT_MESSAGE = 'the following arguments are required: --a';

function buildUnrecognizedArgumentsMessage(tokens) {
  return `unrecognized arguments: ${tokens.join(' ')}`;
}

function buildErrorResult(programName, message) {
  return {
    kind: 'error',
    exitCode: 2,
    output: buildErrorText(programName, message),
  };
}

export function parseCommandLine(args, programName) {
  let optionValue = '';
  let hasOptionValue = false;
  let expectingValue = false;
  let sawHelp = false;
  const unknownTokens = [];

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (expectingValue) {
      if (!canConsumeOptionValue(token)) {
        return buildErrorResult(programName, EXPECTED_VALUE_MESSAGE);
      }

      optionValue = token;
      hasOptionValue = true;
      expectingValue = false;
      continue;
    }

    if (token === '-h' || token === '--help') {
      sawHelp = true;
      continue;
    }

    if (token === '--a') {
      expectingValue = true;
      continue;
    }

    if (token.startsWith('--a=')) {
      optionValue = token.slice(4);
      hasOptionValue = true;
      continue;
    }

    if (token === '--') {
      for (let restIndex = index; restIndex < args.length; restIndex += 1) {
        unknownTokens.push(args[restIndex]);
      }
      break;
    }

    unknownTokens.push(token);
  }

  if (expectingValue) {
    return buildErrorResult(programName, EXPECTED_VALUE_MESSAGE);
  }

  if (sawHelp) {
    return {
      kind: 'help',
      exitCode: 0,
      output: buildHelpText(programName),
    };
  }

  if (!hasOptionValue) {
    return buildErrorResult(programName, REQUIRED_ARGUMENT_MESSAGE);
  }

  if (unknownTokens.length > 0) {
    return buildErrorResult(
      programName,
      buildUnrecognizedArgumentsMessage(unknownTokens),
    );
  }

  return {
    kind: 'run',
    optionValue,
  };
}

