import { parseCommandLine } from './lib/argv_parser.mjs';
import { runSourceExecutable } from './lib/executable_runner.mjs';
import { getProgramName } from './lib/program.mjs';

function main() {
  const programName = getProgramName(process.argv);
  const parsed = parseCommandLine(process.argv.slice(2), programName);

  if (parsed.kind === 'help') {
    process.stdout.write(parsed.output);
    process.exitCode = parsed.exitCode;
    return;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(parsed.output);
    process.exitCode = parsed.exitCode;
    return;
  }

  process.exitCode = runSourceExecutable(parsed.optionValue);
}

main();

